pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Favor small residuals that are multiples of common item patterns
    // This targets the "Best Fit" logic while penalizing fragments that cannot fit typical items (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; 
    }

    // 2. Lookahead Coupling: If next_item_size is large, avoid leaving a residual that is just barely too small
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a dead-zone that cannot accommodate the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward creating a residual that fits the next item perfectly (Good alignment)
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. Density Management: If this is the only bin that fits the item, make it very attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 4. New Bin Threshold: Discourage opening a new bin unless the current residuals are poor
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already quite high
        // or if we are very early in the process (to avoid fragmentation later)
        let progress = step_index as f64 / total_items as f64;
        score += 30.0 + (mean_residual * 0.5) + (progress * 20.0);
    }

    // 5. Modulo-based Harmonic alignment:
    // Reward residuals that leave "round" numbers (e.g., multiples of 10) for future items
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space (fragmentation)
    // We favor post_residual being as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // heavily reward this bin to keep the next item packed tightly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the 
    // current fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin, decreases as the stream progresses
        // to allow for more flexibility toward the end of the stream.
        score += 45.0 * (1.0 - progress * 0.5);
    } else {
        // 4. Global State Awareness: If we have many open bins, penalize 
        // using a bin that leaves a large residual, encouraging consolidation.
        if open_bins_count > 5 {
            score += (post_residual as f64) * (open_bins_count as f64 * 0.1);
        }
    }

    // 5. Critical Constraint: If this is the only bin that fits the item 
    // (fitting_bins_count == 1), we strongly prefer this bin to avoid 
    // opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Variance Penalty: Discourage increasing the mean_residual of open bins.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the residual space after placement.
    // Minimizing this is the Best-Fit strategy.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin when existing bins could accommodate the item.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Only open a new bin if the item is large or we are early in the stream.
        // If fitting_bins_count is low, we are constrained; penalize opening new bins.
        score += 45.0 + (progress * 20.0);
    }

    // Lookahead: If the next item is large, favor bins that can still accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit both current and next items.
            score -= 15.0;
        } else if post_residual > 0 && post_residual < 20 {
            // Penalize creating "fragmented" space (small slivers).
            score += 10.0;
        }
    }

    // Global state optimization:
    // If we have many open bins, prioritize filling the ones with the lowest residuals first
    // to consolidate space.
    if fitting_bins_count > 1 {
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;
    }

    // Tight fit reward: Perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero,
    // as they create "dead space" that cannot accommodate future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Logic: If the next item exists, favor placements that leave enough
    // room for it. If post_residual is smaller than next_item_size, we penalize the bin
    // unless it results in a perfect fit (post_residual == 0).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 3. Density Balancing: If we have many open bins, discourage opening new ones 
    // (bin_residual == bin_capacity) unless the mean_residual is very high.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Penalty for opening a new bin: base cost + mean_residual tax
            score += 45.0 + mean_residual;
        }
    } else {
        // 4. Fitting Constraint: If this is the only bin that fits, prioritize it heavily
        // to avoid unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 5. Progress Normalization: As the stream nears completion, become more aggressive
    // about filling existing bins (minimizing total bins used).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}
